(() => {
const root=document.querySelector('#tt-content'),guide=globalThis.sportGuide;
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm'}).format(new Date());
const date=new URLSearchParams(location.search).get('date')||today;
const event=guide?.events.find(e=>e.sport==='Bordtennis'&&e.date===date);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
if(!event||!['2026-11-03','2026-11-04','2026-11-05'].includes(date)){root.innerHTML='<section class="nhl-card"><h1>Bordtennis</h1><p>Ingen match är verifierad i underlaget för det valda datumet.</p><a href="index.html">Till dagens sport</a></section>';return;}
const current=date==='2026-11-04',nov5=date==='2026-11-05';
const club=(name,country)=>`<div class="club"><span class="club-label">SPELARE</span><div class="football-badge" aria-hidden="true">${country}</div><h1>${name}</h1><p>${country==='SWE'?'Sverige':country==='KOR'?'Sydkorea':'Tyskland'}</p></div>`;
root.innerHTML=`<section class="match-hero"><p class="eyebrow">BORDTENNIS · WTT CHAMPIONS FRANKFURT</p><div class="matchup">${nov5?club('Kristian Karlsson','SWE'):current?club('Lim Jonghoon','KOR'):club('Dang Qiu','GER')}<div class="versus"><span>MOT</span><i></i></div>${nov5?club('Oh Junsung','KOR'):current?club('Anton Källberg','SWE'):club('Elias Ranefur','SWE')}</div><p class="venue-line"><span>MATCHARENA</span><b>Süwag Energie ARENA · Frankfurt</b></p><p class="football-kickoff">${nov5?'Torsdag 5 november 2026 · Matchstart <b>15.20</b> enligt Svenska Bordtennisförbundet':current?'Onsdag 4 november 2026 · Matchstart <b>19.05</b> enligt Svenska Bordtennisförbundet':'Tisdag 3 november 2026 · Matchstart <b>18.30</b> enligt SVT Text'}</p><p class="football-broadcast">Sändningsstart <b>${esc(event.time)}</b> · SVT Play · Svensk tid</p><div class="football-actions">${link(event.broadcastUrl,'Se sändningen')}${(current||nov5)?link(nov5?'https://sbtf.se/landslag/elias-utslagen-mot-dang-qiu-i-frankfurt/':'https://sbtf.se/landslag/truls-foll-i-semin-i-montpellier-nu-vantar-wtt-champions-frankfurt/','Matchtid hos Svenska Bordtennisförbundet'):link('https://www.svt.se/text-tv/399','Matchtid hos SVT')}</div><p class="data-note">Matchdagens resultat och vinnare döljs. Starttider kan ändras.</p></section><section class="nhl-grid"><article class="nhl-card"><p class="eyebrow dark">VÄRLDSRANKING FÖRE MATCHEN</p><h2>Spelarnas ranking</h2><div class="stand-row"><span>${nov5?'SWE':current?'KOR':'GER'}</span><div><b>${nov5?'Kristian Karlsson':current?'Lim Jonghoon':'Dang Qiu'}</b><span>Aktuell placering ej verifierad i officiellt underlag</span></div><strong>–</strong></div><div class="stand-row"><span>${nov5?'KOR':'SWE'}</span><div><b>${nov5?'Oh Junsung':current?'Anton Källberg':'Elias Ranefur'}</b><span>${current?'Placering enligt SVT:s guide, uppdaterad 3 november':'Aktuell placering ej verifierad i officiellt underlag'}</span></div><strong>${current?'#25':'–'}</strong></div>${link('https://www.ittf.com/rankings/','ITTF:s officiella ranking')}${current?link('https://www.svt.se/sport/bordtennis/sa-sander-svt-bordtennis-2026','SVT:s guide: Källberg 25'):''}</article><article class="nhl-card"><p class="eyebrow dark">INBÖRDES MÖTEN</p><h2>Äldre matcher</h2><p>Inga äldre inbördes resultat har kunnat verifieras i det tillgängliga officiella underlaget. Dagens match visas aldrig i resultatlistan.</p>${link('https://www.worldtabletennis.com/eventslist','WTT:s tävlingscenter')}</article></section><section class="map-section"><div><p class="eyebrow">VAR MATCHEN SPELAS</p><h2>Frankfurt.<br>Världstouren.</h2><div class="map-legend"><p><b>Süwag Energie ARENA</b><span>Frankfurt am Main · Tyskland</span></p></div>${link('https://www.openstreetmap.org/search?query=S%C3%BCwag%20Energie%20ARENA%20Frankfurt','Sök matcharenan')}</div><div id="tt-map" class="nhl-real-map"><p>Kartan kunde inte laddas. Använd arenalänken.</p></div></section><section class="football-sources"><h2>Källor och matchfakta</h2><p>Spelare och sändningsstart: SVT Play. Matchstart: Svenska Bordtennisförbundet / SVT Text. Arena: Tischtennis Baden-Württemberg. Ranking och äldre resultat anges endast när de kan verifieras. Datum för detta underlag: ${esc(date)}.</p><div class="football-actions">${link(event.sourceUrl,'SVT Play')}${link('https://www.ttbw.de/news/artikel/wtt-champions-frankfurt-3-bis-8-november-in-der-suewag-energie-arena/','Tävlingsarena')}${link('https://www.ittf.com/rankings/','ITTF')}</div></section>`;
// The city marker is deliberately labelled as approximate, not an exact arena entrance.
if(typeof L!=='undefined'){document.querySelector('#tt-map').innerHTML='';const map=L.map('tt-map',{scrollWheelZoom:false}).setView([50.11,8.68],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap'}).addTo(map);L.marker([50.11,8.68]).addTo(map).bindPopup('Frankfurt · ungefärlig tävlingsort');}
})();
